            new Quote { Id = "https://zh.wikiquote.org/wiki/严复", Text = "“故学者必以道为归。”", Author = "严复" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/严复", Text = "“人生在世，不如意事常八九。”", Author = "严复" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/严复", Text = "“故君子处忧患，则慎；处欢乐，则戒。”", Author = "严复" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/严复", Text = "“以防不虞，以备非常。”", Author = "严复" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/严复", Text = "“论今日中国，宜讲求群学。”", Author = "严复" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/严复", Text = "“群学则近于名学，名学又近于逻辑学。”", Author = "严复" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/严复", Text = "“而根本之所在，则在哲学者。”", Author = "严复" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/严复", Text = "“天下古今之变，不过伦常之变。”", Author = "严复" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/严复", Text = "“而伦常之变，又不过名教之变。”", Author = "严复" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/严复", Text = "“贫者，非恶者也，贫者，所以忧思者也。”", Author = "严复" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/严复", Text = "“忧思者，非恶者也，忧思者，所以忧民者也。”", Author = "严复" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/严复", Text = "“忧民者，非恶者也，忧民者，所以忧天下者也。”", Author = "严复" },
        };
    }
